172	    public String getCustomerCode() {
173	        return this.customerCode;
174	    }
175	
176	    public void setCustomerCode(String customerCode) {
177	        this.customerCode = customerCode;
178	    }
179	
180	    /**
181	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
182	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
183	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
184	     * both the customer code and registration date have been assigned.
185	     */
186	    @Transient
