335	     * The id of the already-stored owner this owner softly matched on create (same last
336	     * name and postcode, different telephone), or {@code null} when it matched none.
337	     */
338	    public Integer getPossibleDuplicateOf() {
339	        return this.possibleDuplicateOf;
340	    }
341	
342	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
343	        this.possibleDuplicateOf = possibleDuplicateOf;
344	    }
345	
346	    protected Set<Pet> getPetsInternal() {
347	        if (this.pets == null) {
348	            this.pets = new HashSet<>();
349	        }
350	        return this.pets;
351	    }
352	
353	    protected void setPetsInternal(Set<Pet> pets) {
354	        this.pets = pets;
355	    }
356	
357	    public List<Pet> getPets() {
358	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
359	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
360	        return Collections.unmodifiableList(sortedPets);
361	    }
362	
363	    public void setPets(List<Pet> pets) {
364	        this.pets = new HashSet<>(pets);
365	    }
366	
367	    public void addPet(Pet pet) {
368	        getPetsInternal().add(pet);
369	        pet.setOwner(this);
370	    }
371	
372	    /**
373	     * Return the Pet with the given name, or null if none found for this Owner.
374	     *
375	     * @param name to test
376	     * @return true if pet name is already in use
377	     */
378	    public Pet getPet(String name) {
379	        return getPet(name, false);
380	    }
381	
382	    /**
383	     * Return the Pet with the given name, or null if none found for this Owner.
384	     *
385	     * @param name to test
386	     * @return true if pet name is already in use
387	     */
388	    public Pet getPet(String name, boolean ignoreNew) {
389	        name = name.toLowerCase();
390	        for (Pet pet : getPetsInternal()) {
391	            if (!ignoreNew || !pet.isNew()) {
392	                String compName = pet.getName();
393	                compName = compName.toLowerCase();
394	                if (compName.equals(name)) {
395	                    return pet;
396	                }
397	            }
398	        }
399	        return null;
400	    }
401	
402	    public Pet getPet(Integer petId) {
403	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
404	    }
405	
406	    @Override
407	    public String toString() {
408	        return new ToStringCreator(this)
409	
410	            .append("id", this.getId())
411	            .append("new", this.isNew())
412	            .append("lastName", this.getLastName())
413	            .append("firstName", this.getFirstName())
414	            .append("address", this.address)
415	            .append("city", this.city)
416	            .append("telephone", this.telephone)
417	            .append("email", this.email)
418	            .append("registrationDate", this.registrationDate)
419	            .append("customerCode", this.customerCode)
420	            .toString();
421	    }
422	}
